const form=document.querySelector('#auditForm'),result=document.querySelector('#result'),body=document.querySelector('#resultBody');let latest=null;
const money=n=>'₹'+Number(n).toLocaleString('en-IN',{maximumFractionDigits:2});
async function api(path,options={}){const r=await fetch('/api'+path,{headers:{'Content-Type':'application/json'},...options});const data=await r.json();if(!r.ok)throw new Error(data.detail||'Request failed');return data}
(async()=>{try{const h=await api('/health');document.querySelector('#aiStatus').textContent=h.ai_configured?'Configured':'Not configured'}catch{document.querySelector('#aiStatus').textContent='API offline'}})();
form.addEventListener('submit',async e=>{e.preventDefault();const f=new FormData(form);try{const history=JSON.parse(f.get('history'));const payload={period_start:f.get('period_start'),period_end:f.get('period_end'),units:Number(f.get('units')),amount:Number(f.get('amount')),period_days:Number(f.get('period_days')),fixed_charge:Number(f.get('fixed_charge')),tax_rate_pct:Number(f.get('tax_rate_pct')),per_unit_rate:f.get('per_unit_rate')===""?null:Number(f.get('per_unit_rate')),history};const data=await api('/audits',{method:'POST',body:JSON.stringify(payload)});latest=data;result.classList.remove('hidden');document.querySelector('#auditId').textContent='AUDIT #'+data.id;const r=data.result;body.innerHTML=`<div class="metric-row"><div class="metric"><small>Daily consumption</small><b>${r.daily_units} kWh</b></div><div class="metric"><small>Daily bill amount</small><b>${money(r.daily_amount)}</b></div><div class="metric"><small>Prior periods used</small><b>${r.history_periods}</b></div><div class="metric"><small>Screening points</small><b>${r.screening_points}</b></div></div><p class="hint">${r.notice}</p>${r.baseline?`<div class="finding"><b>Historical baseline</b><p>Median daily usage: ${r.baseline.daily_units_median} kWh · Median daily amount: ${money(r.baseline.daily_amount_median)}<br>Usage change: ${r.baseline.usage_change_pct}% · Amount change: ${r.baseline.amount_change_pct}%</p></div>`:''}${r.signals.length?r.signals.map(s=>`<div class="finding"><b>${s.family.replaceAll('_',' ').toUpperCase()}</b><p>${s.message}</p><p>${Object.entries(s).filter(([k])=>!['family','severity','message'].includes(k)).map(([k,v])=>`${k.replaceAll('_',' ')}: ${v}`).join(' · ')}</p></div>`).join(''):'<div class="finding"><b>No screening signal from the configured rules</b><p>This does not prove the bill is correct. Review the source bill and tariff details.</p></div>'}`;result.scrollIntoView({behavior:'smooth'});}catch(err){alert(err.message)}});
document.querySelector('#explainBtn').addEventListener('click',async()=>{if(!latest)return;const out=document.querySelector('#aiExplanation');out.textContent='Asking the configured AI provider…';try{const d=await api('/ai/explain',{method:'POST',body:JSON.stringify({audit_result:latest.result})});out.textContent=d.explanation}catch(e){out.textContent=e.message}});
